def bus_timer(time_str):
    hours, minutes = map(int, time_str.split(':'))
    total_minutes = hours * 60 + minutes

    # Calculate the time until the next bus
    if total_minutes % 15 == 0:
        return 14  # If already on a bus time, wait for the next one
    else:
        return 15 - (total_minutes % 15) - 5  # Subtract 5 minutes walking time
